    15→
    16→import static ethereum.ckzg4844.CKZG4844JNI.BYTES_PER_CELL;
    17→import static ethereum.ckzg4844.CKZG4844JNI.BYTES_PER_COMMITMENT;
    18→
    19→import ethereum.ckzg4844.CKZG4844JNI;
    20→import ethereum.ckzg4844.CellsAndProofs;
    21→import java.util.List;
    22→import java.util.Optional;
    23→import java.util.stream.IntStream;
    24→import org.apache.logging.log4j.LogManager;
    25→import org.apache.logging.log4j.Logger;
    26→import org.apache.tuweni.bytes.Bytes;
    27→
    28→/**
    29→ * Wrapper around jc-kzg-4844
    30→ *
    31→ * <p>This class should be a singleton
    32→ */
    33→final class CKZG4844 implements KZG {
    34→
    35→  private static final Logger LOG = LogManager.getLogger();
    36→
    37→  @SuppressWarnings("NonFinalStaticField")
    38→  private static CKZG4844 instance;
    39→
    40→  static synchronized CKZG4844 getInstance() {
    41→    if (instance == null) {
    42→      instance = new CKZG4844();
    43→    }
    44→    return instance;
    45→  }
    46→
    47→  private Optional<String> loadedTrustedSetupFile = Optional.empty();
    48→
    49→  private CKZG4844() {
    50→    try {
    51→      CKZG4844JNI.loadNativeLibrary();
    52→      LOG.info("Loaded C-KZG-4844 library");
    53→    } catch (final Exception ex) {
    54→      throw new KZGException("Failed to load C-KZG-4844 library", ex);
    55→    }
    56→  }
    57→
    58→  /** Only one trusted setup at a time can be loaded. */
    59→  @Override
    60→  public synchronized void loadTrustedSetup(final String trustedSetupFile, final int kzgPrecompute)
    61→      throws KZGException {
    62→    if (loadedTrustedSetupFile.isPresent()
    63→        && loadedTrustedSetupFile.get().equals(trustedSetupFile)) {
    64→      LOG.trace("Trusted setup from {} is already loaded", trustedSetupFile);
    65→      return;
    66→    }
    67→    try {
    68→      loadedTrustedSetupFile.ifPresent(
    69→          currentTrustedSetupFile -> {
    70→            LOG.debug(
    71→                "Freeing current trusted setup {} in order to load trusted setup from {}",
    72→                currentTrustedSetupFile,
    73→                trustedSetupFile);
    74→            freeTrustedSetup();
    75→          });
    76→      final TrustedSetup trustedSetup = CKZG4844Utils.parseTrustedSetupFile(trustedSetupFile);
    77→      final List<Bytes> g1PointsLagrange = trustedSetup.g1Lagrange();
    78→      final List<Bytes> g2PointsMonomial = trustedSetup.g2Monomial();
    79→      final List<Bytes> g1PointsMonomial = trustedSetup.g1Monomial();
    80→      CKZG4844JNI.loadTrustedSetup(
    81→          CKZG4844Utils.flattenG1Points(g1PointsMonomial),
    82→          CKZG4844Utils.flattenG1Points(g1PointsLagrange),
    83→          CKZG4844Utils.flattenG2Points(g2PointsMonomial),
    84→          kzgPrecompute);
    85→      LOG.debug("Loaded trusted setup from {}", trustedSetupFile);
    86→      loadedTrustedSetupFile = Optional.of(trustedSetupFile);
    87→    } catch (final Exception ex) {
    88→      throw new KZGException("Failed to load trusted setup from " + trustedSetupFile, ex);
    89→    }
    90→  }
    91→
    92→  @Override
    93→  public synchronized void freeTrustedSetup() throws KZGException {
    94→    try {
    95→      CKZG4844JNI.freeTrustedSetup();
    96→      loadedTrustedSetupFile = Optional.empty();
    97→      LOG.debug("Trusted setup was freed");
    98→    } catch (final Exception ex) {
    99→      throw new KZGException("Failed to free trusted setup", ex);
   100→    }
   101→  }
   102→
   103→  @Override
   104→  public boolean verifyBlobKzgProof(
   105→      final Bytes blob, final KZGCommitment kzgCommitment, final KZGProof kzgProof)
   106→      throws KZGException {
   107→    try {
   108→      return CKZG4844JNI.verifyBlobKzgProof(
   109→          blob.toArrayUnsafe(), kzgCommitment.toArrayUnsafe(), kzgProof.toArrayUnsafe());
   110→    } catch (final Exception ex) {
   111→      throw new KZGException(
   112→          "Failed to verify blob and commitment against KZG proof " + kzgProof, ex);
   113→    }
   114→  }
   115→
   116→  @Override
   117→  public boolean verifyBlobKzgProofBatch(
   118→      final List<Bytes> blobs,
   119→      final List<KZGCommitment> kzgCommitments,
   120→      final List<KZGProof> kzgProofs)
   121→      throws KZGException {
   122→    try {
   123→      final byte[] blobsBytes = CKZG4844Utils.flattenBlobs(blobs);
   124→      final byte[] commitmentsBytes = CKZG4844Utils.flattenCommitments(kzgCommitments);
   125→      final byte[] proofsBytes = CKZG4844Utils.flattenProofs(kzgProofs);
   126→      return CKZG4844JNI.verifyBlobKzgProofBatch(
   127→          blobsBytes, commitmentsBytes, proofsBytes, blobs.size());
   128→    } catch (final Exception ex) {
   129→      throw new KZGException(
   130→          "Failed to verify blobs and commitments against KZG proofs " + kzgProofs, ex);
   131→    }
   132→  }
   133→
   134→  @Override
   135→  public KZGCommitment blobToKzgCommitment(final Bytes blob) throws KZGException {
   136→    try {
   137→      final byte[] commitmentBytes = CKZG4844JNI.blobToKzgCommitment(blob.toArrayUnsafe());
   138→      return KZGCommitment.fromArray(commitmentBytes);
   139→    } catch (final Exception ex) {
   140→      throw new KZGException("Failed to produce KZG commitment from blob", ex);
   141→    }
   142→  }
   143→
   144→  @Override
   145→  public KZGProof computeBlobKzgProof(final Bytes blob, final KZGCommitment kzgCommitment)
   146→      throws KZGException {
   147→    try {
   148→      final byte[] proof =
   149→          CKZG4844JNI.computeBlobKzgProof(blob.toArrayUnsafe(), kzgCommitment.toArrayUnsafe());
   150→      return KZGProof.fromArray(proof);
   151→    } catch (final Exception ex) {
   152→      throw new KZGException(
   153→          "Failed to compute KZG proof for blob with commitment " + kzgCommitment, ex);
   154→    }
   155→  }
   156→
   157→  @Override
   158→  public List<KZGCell> computeCells(final Bytes blob) throws KZGException {
   159→    try {
   160→      final byte[] cells = CKZG4844JNI.computeCells(blob.toArrayUnsafe());
   161→      return KZGCell.splitBytes(Bytes.wrap(cells));
   162→    } catch (final Exception ex) {
   163→      throw new KZGException("Failed to compute KZG cells for blob " + blob.toShortHexString(), ex);
   164→    }
   165→  }
   166→
   167→  @Override
   168→  public List<KZGCellAndProof> computeCellsAndProofs(final Bytes blob) {
   169→    final CellsAndProofs cellsAndProofs =
   170→        CKZG4844JNI.computeCellsAndKzgProofs(blob.toArrayUnsafe());
   171→    final List<KZGCell> cells = KZGCell.splitBytes(Bytes.wrap(cellsAndProofs.getCells()));
   172→    final List<KZGProof> proofs = KZGProof.splitBytes(Bytes.wrap(cellsAndProofs.getProofs()));
   173→    if (cells.size() != proofs.size()) {
   174→      throw new KZGException("Cells and proofs size differ");
   175→    }
   176→    return IntStream.range(0, cells.size())
   177→        .mapToObj(i -> new KZGCellAndProof(cells.get(i), proofs.get(i)))
   178→        .toList();
   179→  }
   180→
   181→  @Override
   182→  public boolean verifyCellProofBatch(
   183→      final List<KZGCommitment> commitments,
   184→      final List<KZGCellWithColumnId> cellWithIdList,
   185→      final List<KZGProof> proofs) {
   186→    if (commitments.size() != cellWithIdList.size() || cellWithIdList.size() != proofs.size()) {
   187→      throw new KZGException("Cells, proofs and commitments sizes should match");
   188→    }
   189→    return CKZG4844JNI.verifyCellKzgProofBatch(
   190→        CKZG4844Utils.flattenBytes(
   191→            commitments.stream()
   192→                .map(kzgCommitment -> (Bytes) kzgCommitment.getBytesCompressed())
   193→                .toList(),
   194→            commitments.size() * BYTES_PER_COMMITMENT),
   195→        cellWithIdList.stream()
   196→            .mapToLong(cellWithIds -> cellWithIds.columnId().id().longValue())
   197→            .toArray(),
   198→        CKZG4844Utils.flattenBytes(
   199→            cellWithIdList.stream().map(cellWithIds -> cellWithIds.cell().bytes()).toList(),
   200→            cellWithIdList.size() * BYTES_PER_CELL),
   201→        CKZG4844Utils.flattenProofs(proofs));
   202→  }
   203→
   204→  @Override
   205→  public List<KZGCellAndProof> recoverCellsAndProofs(final List<KZGCellWithColumnId> cells) {
   206→    final long[] cellIds = cells.stream().mapToLong(c -> c.columnId().id().longValue()).toArray();
   207→    final byte[] cellBytes =
   208→        CKZG4844Utils.flattenBytes(
   209→            cells.stream().map(c -> c.cell().bytes()).toList(), cells.size() * BYTES_PER_CELL);
   210→    final CellsAndProofs cellsAndProofs = CKZG4844JNI.recoverCellsAndKzgProofs(cellIds, cellBytes);
   211→    final List<KZGCell> fullCells = KZGCell.splitBytes(Bytes.wrap(cellsAndProofs.getCells()));
   212→    final List<KZGProof> fullProofs = KZGProof.splitBytes(Bytes.wrap(cellsAndProofs.getProofs()));
   213→    if (fullCells.size() != fullProofs.size()) {
   214→      throw new KZGException("Cells and proofs size differ");
   215→    }
   216→    return IntStream.range(0, fullCells.size())
   217→        .mapToObj(i -> new KZGCellAndProof(fullCells.get(i), fullProofs.get(i)))
   218→        .toList();
   219→  }
   220→}
