   368→  /**
   369→   * Return the full ``ExtendedMatrix``.
   370→   *
   371→   * <p>This helper demonstrates the relationship between blobs and ``ExtendedMatrix``.
   372→   *
   373→   * <p>>The data structure for storing cells is implementation-dependent.
   374→   */
   375→  public List<List<MatrixEntry>> computeExtendedMatrixAndProofs(
   376→      final List<Blob> blobs, final KZG kzg) {
   377→    return IntStream.range(0, blobs.size())
   378→        .parallel()
   379→        .mapToObj(
   380→            blobIndex -> {
   381→              final List<KZGCellAndProof> kzgCellAndProofs =
   382→                  kzg.computeCellsAndProofs(blobs.get(blobIndex).getBytes());
   383→              final List<MatrixEntry> row = new ArrayList<>();
   384→              for (int cellIndex = 0; cellIndex < kzgCellAndProofs.size(); ++cellIndex) {
   385→                row.add(
   386→                    schemaDefinitionsFulu
   387→                        .getMatrixEntrySchema()
   388→                        .create(
   389→                            kzgCellAndProofs.get(cellIndex).cell(),
   390→                            kzgCellAndProofs.get(cellIndex).proof(),
   391→                            blobIndex,
   392→                            cellIndex));
   393→              }
   394→              return row;
   395→            })
   396→        .toList();
   397→  }
   398→
   399→  public List<List<MatrixEntry>> computeExtendedMatrix(
   400→      final List<BlobAndCellProofs> blobAndCellProofsList, final KZG kzg) {
   401→    return IntStream.range(0, blobAndCellProofsList.size())
   402→        .parallel()
   403→        .mapToObj(
   404→            blobIndex -> {
   405→              final BlobAndCellProofs blobAndCellProofs = blobAndCellProofsList.get(blobIndex);
   406→              final List<KZGCell> kzgCells = kzg.computeCells(blobAndCellProofs.blob().getBytes());
   407→              final List<MatrixEntry> row = new ArrayList<>();
   408→              for (int cellIndex = 0; cellIndex < kzgCells.size(); ++cellIndex) {
   409→                row.add(
   410→                    schemaDefinitionsFulu
   411→                        .getMatrixEntrySchema()
   412→                        .create(
   413→                            kzgCells.get(cellIndex),
   414→                            blobAndCellProofs.cellProofs().get(cellIndex),
   415→                            blobIndex,
   416→                            cellIndex));
   417→              }
   418→              return row;
   419→            })
   420→        .toList();
   421→  }
   422→
   423→  @VisibleForTesting
   424→  public List<DataColumnSidecar> constructDataColumnSidecars(
   425→      final BeaconBlock beaconBlock,
   426→      final SignedBeaconBlockHeader signedBeaconBlockHeader,
   427→      final List<List<MatrixEntry>> extendedMatrix) {
   428→    if (extendedMatrix.isEmpty()) {
   429→      return Collections.emptyList();
   430→    }
   431→
   432→    final SszList<SszKZGCommitment> sszKZGCommitments;
   433→    final List<Bytes32> kzgCommitmentsInclusionProof;
   434→    if (beaconBlock.isBlinded()) {
   435→      final BlindedBeaconBlockBodyDeneb beaconBlockBody =
   436→          BlindedBeaconBlockBodyDeneb.required(beaconBlock.getBody());
   437→      sszKZGCommitments = beaconBlockBody.getBlobKzgCommitments();
   438→      kzgCommitmentsInclusionProof = computeDataColumnKzgCommitmentsInclusionProof(beaconBlockBody);
   439→    } else {
   440→      final BeaconBlockBodyDeneb beaconBlockBody =
   441→          BeaconBlockBodyDeneb.required(beaconBlock.getBody());
   442→      sszKZGCommitments = beaconBlockBody.getBlobKzgCommitments();
   443→      kzgCommitmentsInclusionProof = computeDataColumnKzgCommitmentsInclusionProof(beaconBlockBody);
   444→    }
   445→
   446→    return constructDataColumnSidecars(
   447→        signedBeaconBlockHeader, sszKZGCommitments, kzgCommitmentsInclusionProof, extendedMatrix);
   448→  }
   449→
   450→  private List<DataColumnSidecar> constructDataColumnSidecars(
   451→      final SignedBeaconBlockHeader signedBeaconBlockHeader,
   452→      final SszList<SszKZGCommitment> sszKZGCommitments,
   453→      final List<Bytes32> kzgCommitmentsInclusionProof,
   454→      final List<List<MatrixEntry>> extendedMatrix) {
   455→    if (extendedMatrix.isEmpty()) {
   456→      return Collections.emptyList();
   457→    }
   458→
   459→    final DataColumnSchema dataColumnSchema = schemaDefinitionsFulu.getDataColumnSchema();
   460→    final DataColumnSidecarSchema dataColumnSidecarSchema =
   461→        schemaDefinitionsFulu.getDataColumnSidecarSchema();
   462→    final SszListSchema<SszKZGProof, ?> kzgProofsSchema =
   463→        dataColumnSidecarSchema.getKzgProofsSchema();
   464→
   465→    final int columnCount = extendedMatrix.getFirst().size();
   466→
   467→    return IntStream.range(0, columnCount)
   468→        .mapToObj(
   469→            cellID -> {
   470→              List<MatrixEntry> columnData =
   471→                  extendedMatrix.stream().map(row -> row.get(cellID)).toList();
   472→              List<Cell> columnCells = columnData.stream().map(MatrixEntry::getCell).toList();
   473→
   474→              SszList<SszKZGProof> columnProofs =
   475→                  columnData.stream()
   476→                      .map(MatrixEntry::getKzgProof)
   477→                      .map(SszKZGProof::new)
   478→                      .collect(kzgProofsSchema.collector());
   479→              final DataColumn dataColumn = dataColumnSchema.create(columnCells);
   480→
   481→              return dataColumnSidecarSchema.create(
   482→                  UInt64.valueOf(cellID),
   483→                  dataColumn,
   484→                  sszKZGCommitments,
   485→                  columnProofs,
   486→                  signedBeaconBlockHeader,
   487→                  kzgCommitmentsInclusionProof);
   488→            })
   489→        .toList();
   490→  }
   491→
   492→  public List<DataColumnSidecar> reconstructAllDataColumnSidecars(
   493→      final Collection<DataColumnSidecar> existingSidecars, final KZG kzg) {
   494→    if (existingSidecars.size() < (specConfigFulu.getNumberOfColumns() / 2)) {
   495→      final Optional<DataColumnSidecar> maybeSidecar = existingSidecars.stream().findAny();
   496→      throw new IllegalArgumentException(
   497→          String.format(
   498→              "Number of sidecars must be greater than or equal to the half of column count, slot: %s; columns: found %s, needed at least %d",
   499→              maybeSidecar.isPresent() ? maybeSidecar.get().getSlot().toString() : "unknown",
   500→              existingSidecars.size(),
   501→              specConfigFulu.getNumberOfColumns() / 2));
   502→    }
   503→    final List<List<MatrixEntry>> columnBlobEntries =
   504→        existingSidecars.stream()
   505→            .map(
   506→                sidecar ->
   507→                    IntStream.range(0, sidecar.getDataColumn().size())
   508→                        .mapToObj(
   509→                            rowIndex ->
   510→                                schemaDefinitionsFulu
   511→                                    .getMatrixEntrySchema()
   512→                                    .create(
   513→                                        sidecar.getDataColumn().get(rowIndex),
   514→                                        sidecar.getSszKZGProofs().get(rowIndex).getKZGProof(),
   515→                                        sidecar.getIndex(),
   516→                                        UInt64.valueOf(rowIndex)))
   517→                        .toList())
   518→            .toList();
   519→    final List<List<MatrixEntry>> blobColumnEntries = transpose(columnBlobEntries);
   520→    final List<List<MatrixEntry>> extendedMatrix = recoverMatrix(blobColumnEntries, kzg);
   521→    final DataColumnSidecar anyExistingSidecar =
   522→        existingSidecars.stream().findFirst().orElseThrow();
   523→    final SignedBeaconBlockHeader signedBeaconBlockHeader =
   524→        anyExistingSidecar.getSignedBeaconBlockHeader();
   525→    return constructDataColumnSidecars(
   526→        signedBeaconBlockHeader,
   527→        anyExistingSidecar.getSszKZGCommitments(),
   528→        anyExistingSidecar.getKzgCommitmentsInclusionProof().asListUnboxed(),
   529→        extendedMatrix);
   530→  }
   531→
   532→  /**
   533→   * Return the recovered extended matrix.
   534→   *
   535→   * <p>This helper demonstrates how to apply ``recover_cells_and_kzg_proofs``.
   536→   *
   537→   * <p>The data structure for storing cells is implementation-dependent.
   538→   */
   539→  public List<List<MatrixEntry>> recoverMatrix(
   540→      final List<List<MatrixEntry>> partialMatrix, final KZG kzg) {
   541→    return IntStream.range(0, partialMatrix.size())
   542→        .parallel()
   543→        .mapToObj(
   544→            blobIndex -> {
   545→              final List<KZGCellWithColumnId> cellWithColumnIds =
   546→                  partialMatrix.get(blobIndex).stream()
   547→                      .filter(entry -> entry.getRowIndex().intValue() == blobIndex)
   548→                      .map(
   549→                          entry ->
   550→                              new KZGCellWithColumnId(
   551→                                  new KZGCell(entry.getCell().getBytes()),
   552→                                  new KZGCellID(entry.getColumnIndex())))
   553→                      .toList();
   554→              final List<KZGCellAndProof> kzgCellAndProofs =
   555→                  kzg.recoverCellsAndProofs(cellWithColumnIds);
   556→              return IntStream.range(0, kzgCellAndProofs.size())
   557→                  .mapToObj(
   558→                      kzgCellAndProofIndex ->
   559→                          schemaDefinitionsFulu
   560→                              .getMatrixEntrySchema()
   561→                              .create(
   562→                                  kzgCellAndProofs.get(kzgCellAndProofIndex).cell(),
   563→                                  kzgCellAndProofs.get(kzgCellAndProofIndex).proof(),
   564→                                  kzgCellAndProofIndex,
   565→                                  blobIndex))
   566→                  .toList();
   567→            })
   568→        .toList();
   569→  }
   570→
   571→  public int getSamplingGroupCount(final int custodyRequirement) {
   572→    return Math.max(custodyRequirement, specConfigFulu.getSamplesPerSlot());
   573→  }
   574→
   575→  private static <T> List<List<T>> transpose(final List<List<T>> matrix) {
   576→    final int rowCount = matrix.size();
   577→    final int colCount = matrix.getFirst().size();
   578→    final List<List<T>> ret =
   579→        Stream.generate(() -> (List<T>) new ArrayList<T>(rowCount)).limit(colCount).toList();
   580→
   581→    for (int row = 0; row < rowCount; row++) {
   582→      if (matrix.get(row).size() != colCount) {
   583→        throw new IllegalArgumentException("Different number columns in the matrix");
   584→      }
   585→      for (int col = 0; col < colCount; col++) {
   586→        final T val = matrix.get(row).get(col);
   587→        ret.get(col).add(row, val);
   588→      }
   589→    }
   590→    return ret;
   591→  }
   592→
   593→  @Override
   594→  public boolean isAvailabilityOfBlobSidecarsRequiredAtEpoch(
   595→      final UInt64 currentEpoch, final UInt64 epoch) {
   596→    return !epoch.isGreaterThanOrEqualTo(specConfigFulu.getFuluForkEpoch());
   597→  }
   598→
   599→  public boolean isAvailabilityOfDataColumnSidecarsRequiredAtEpoch(
   600→      final UInt64 currentEpoch, final UInt64 epoch) {
   601→    return currentEpoch
   602→        .minusMinZero(epoch)
   603→        .isLessThanOrEqualTo(specConfigFulu.getMinEpochsForDataColumnSidecarsRequests());
   604→  }
   605→
   606→  // compute_proposer_indices
   607→  @Override
   608→  public List<Integer> computeProposerIndices(
   609→      final BeaconState state,
   610→      final UInt64 epoch,
   611→      final Bytes32 epochSeed,
   612→      final IntList activeValidatorIndices) {
   613→    final UInt64 startSlot = computeStartSlotAtEpoch(epoch);
   614→    return IntStream.range(0, specConfigFulu.getSlotsPerEpoch())
   615→        .mapToObj(
   616→            i -> {
   617→              final Bytes32 seed =
   618→                  Hash.sha256(
   619→                      Bytes.concat(
   620→                          epochSeed.toArray(), uint64ToBytes(startSlot.plus(i)).toArray()));
   621→              return computeProposerIndex(state, activeValidatorIndices, seed);
   622→            })
   623→        .toList();
   624→  }
   625→
   626→  // initialize_proposer_lookahead
   627→  public List<UInt64> initializeProposerLookahead(
   628→      final BeaconStateElectra state, final BeaconStateAccessorsFulu beaconAccessors) {
   629→    final UInt64 currentEpoch = computeEpochAtSlot(state.getSlot());
   630→    return IntStream.rangeClosed(0, specConfigFulu.getMinSeedLookahead())
   631→        .flatMap(
   632→            i ->
   633→                beaconAccessors.getBeaconProposerIndices(state, currentEpoch.plus(i)).stream()
   634→                    .mapToInt(Integer::intValue))
   635→        .mapToObj(UInt64::valueOf)
   636→        .toList();
   637→  }
   638→}
   639→

